function main(input) {
  let essais = 0;
  let trouve = false;
  // Ajoute la limite au parcours.
  for (let n = 0; n < 10; n++) {
    essais++;
    if (n === input.valeurDuCoffre) {
      trouve = true;
      break;
    }
  }
  return { essais, trouve };
}

