files.css:
* {
  box-sizing:border-box
}
body {
  margin:0;
  padding:22px;
  background:#101827;
  color:#e6edf7;
  font:16px/1.6 system-ui
}
h1 {
  font-size:24px
}
main {
  max-width:700px;
  margin:auto
}
label,output {
  display:block;
  margin:14px 0
}
input,select,textarea {
  padding:10px;
  max-width:100%;
  background:#17283d;
  color:white;
  border:1px solid #74def0
}
button {
  padding:10px 16px;
  background:#9be564;
  color:#142115;
  border:0;
  border-radius:5px;
  font-weight:700
}
button:focus-visible,input:focus-visible {
  outline:3px solid #e8c766;
  outline-offset:3px
}
.tag {
  font:12px monospace;
  color:#79e2e2
}
.card {
  padding:16px;
  background:#20334b;
  border:1px solid #4f6482
}
pre {
  white-space:pre-wrap
}

